ALTER TABLE "qti"."declaration" ADD COLUMN "parent_kind" "qti"."node_kind" DEFAULT 0::smallint NOT NULL;
UPDATE "qti"."declaration" AS "d" SET "parent_kind" = "n"."kind" FROM "qti"."node" AS "n" WHERE "n"."id" = "d"."parent";
ALTER TABLE "qti"."declaration" ALTER COLUMN "parent_kind" DROP DEFAULT;

ALTER TABLE "qti"."declaration_identifier" ADD COLUMN "parent_kind" "qti"."node_kind" DEFAULT 0::smallint NOT NULL;
UPDATE "qti"."declaration_identifier" AS "i" SET "parent_kind" = "d"."parent_kind" FROM "qti"."declaration" AS "d" WHERE "d"."node" = "i"."node";
ALTER TABLE "qti"."declaration_identifier" ALTER COLUMN "parent_kind" DROP DEFAULT;

ALTER TABLE "qti"."declaration_name" ADD COLUMN "parent_kind" "qti"."node_kind" DEFAULT 0::smallint NOT NULL;
UPDATE "qti"."declaration_name" AS "m" SET "parent_kind" = "d"."parent_kind" FROM "qti"."declaration" AS "d" WHERE "d"."node" = "m"."node";
ALTER TABLE "qti"."declaration_name" ALTER COLUMN "parent_kind" DROP DEFAULT;

