  "node" "pg_catalog"."uuid" NOT NULL,
  "start" "qti"."__domain_gfw43vigph" NOT NULL,
  "value" "qti"."__text_pwaizaq6lx" NOT NULL,
  "version" "qti"."schema_version" NOT NULL,
