ALTER TABLE "qti"."interaction" ADD COLUMN "module_forms" "qti"."__domain_gfw43vigph" DEFAULT 0::bigint NOT NULL;

ALTER TABLE "qti"."map_key" ADD COLUMN "case_text" "qti"."__text_pwaizaq6lx" DEFAULT ''::"pg_catalog"."text" NOT NULL;
UPDATE "qti"."map_key" AS "k" SET "case_text" = "a"."lexical" FROM "qti"."attribute" AS "a" WHERE "a"."node" = "k"."node" AND "a"."kind" = 168::smallint AND "a"."name" = 105::smallint;
ALTER TABLE "qti"."map_key" ALTER COLUMN "case_text" DROP DEFAULT;

ALTER TABLE "qti"."map_key" ADD COLUMN "folded" boolean DEFAULT false NOT NULL;
UPDATE "qti"."map_key" AS "k" SET "folded" = true FROM "qti"."map_key_type" AS "t" WHERE "t"."node" = "k"."node" AND "t"."base_type" = 3::smallint AND NOT "pg_catalog"."btrim"("pg_catalog"."regexp_replace"("k"."case_text", '[\u0009\u000A\u000D ]+'::"pg_catalog"."text", ' '::"pg_catalog"."text", 'g'::"pg_catalog"."text")) IN ('1'::"pg_catalog"."text", 'true'::"pg_catalog"."text");
ALTER TABLE "qti"."map_key" ALTER COLUMN "folded" DROP DEFAULT;

ALTER TABLE "qti"."map_key" ADD COLUMN "matched" "qti"."__text_pwaizaq6lx" DEFAULT ''::"pg_catalog"."text" NOT NULL;
UPDATE "qti"."map_key" SET "matched" = CASE WHEN "folded" THEN "pg_catalog"."translate"("key", 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'::"pg_catalog"."text", 'abcdefghijklmnopqrstuvwxyz'::"pg_catalog"."text") ELSE "key" END;
ALTER TABLE "qti"."map_key" ALTER COLUMN "matched" DROP DEFAULT;

