ALTER TABLE "qti"."placed_xml_lang" ADD COLUMN "scope" "pg_catalog"."uuid" DEFAULT '00000000-0000-0000-0000-000000000000'::"pg_catalog"."uuid" NOT NULL;
WITH RECURSIVE "up" ("origin", "at", "kind", "parent", "document") AS (
  SELECT "o"."node", "n"."id", "n"."kind", "n"."parent", "n"."document" FROM (SELECT DISTINCT "node" FROM "qti"."placed_xml_lang") AS "o" JOIN "qti"."node" AS "n" ON "n"."id" = "o"."node"
  UNION ALL
  SELECT "u"."origin", "n"."id", "n"."kind", "n"."parent", "n"."document" FROM "up" AS "u" JOIN "qti"."node" AS "n" ON "n"."id" = "u"."parent"
  WHERE "u"."kind" <> 96::smallint AND "u"."parent" <> "u"."document"
)
UPDATE "qti"."placed_xml_lang" AS "x" SET "scope" = CASE WHEN "u"."kind" = 96::smallint THEN "u"."at" ELSE "u"."document" END
FROM "up" AS "u" WHERE "u"."origin" = "x"."node" AND ("u"."kind" = 96::smallint OR "u"."parent" = "u"."document");
ALTER TABLE "qti"."placed_xml_lang" ALTER COLUMN "scope" DROP DEFAULT;

