-- UsageValue.baseType is dropped (declared); its value moves here (decision 427 (4)). Every old row
-- held a spelled base type beside its lexical form under these same two checks, so each is copied.
INSERT INTO "qti"."usage_value_base_type" ("base_type", "base_type_lexical", "node", "text")
SELECT "base_type", "base_type_lexical", "node", "text" FROM "qti"."usage_value";

ALTER TABLE "qti"."xml_lang" ADD COLUMN "scope" "pg_catalog"."uuid" DEFAULT '00000000-0000-0000-0000-000000000000'::"pg_catalog"."uuid" NOT NULL;
WITH RECURSIVE "up" ("origin", "at", "kind", "parent", "document") AS (
  SELECT "o"."node", "n"."id", "n"."kind", "n"."parent", "n"."document" FROM (SELECT "node" FROM "qti"."xml_lang") AS "o" JOIN "qti"."node" AS "n" ON "n"."id" = "o"."node"
  UNION ALL
  SELECT "u"."origin", "n"."id", "n"."kind", "n"."parent", "n"."document" FROM "up" AS "u" JOIN "qti"."node" AS "n" ON "n"."id" = "u"."parent"
  WHERE "u"."kind" <> 96::smallint AND "u"."parent" <> "u"."document"
)
UPDATE "qti"."xml_lang" AS "x" SET "scope" = CASE WHEN "u"."kind" = 96::smallint THEN "u"."at" ELSE "u"."document" END
FROM "up" AS "u" WHERE "u"."origin" = "x"."node" AND ("u"."kind" = 96::smallint OR "u"."parent" = "u"."document");
ALTER TABLE "qti"."xml_lang" ALTER COLUMN "scope" DROP DEFAULT;

