UPDATE "qti"."open_attribute_name" AS "t"
SET "version" = "a"."version"
FROM "qti"."attribute" AS "a"
WHERE "t"."node" = "a"."node" AND "t"."attribute" = "a"."id";

UPDATE "qti"."open_attribute_name" AS "t"
SET "governs" = "a"."governs"
FROM "qti"."attribute" AS "a"
WHERE "t"."node" = "a"."node" AND "t"."attribute" = "a"."id";

